import { realtime } from "../../../firebase/firebaseConfig";
import { collection, addDoc} from "firebase/firestore";
import { db} from "../../../firebase/firebaseConfig";
import { agregarVentas, editarVentas, finalizarTurno, finishLoading, iniciarTurno, startLoading } from "./sidebarSlice";
import { get, ref, remove, set } from "firebase/database";
import { agregarNuevaVenta } from "../../../pages/ventas/slices/ventasSlice";

export const iniciarTurnoDB = (detallesTurno) => {
    return async( dispatch ) => {
        let newDetallesTurno = { 
            turno:'TURNO', 
            inicio:'', 
            fin:'..:..:..', 
            ventas: [],
            //pagos: [],
            precioBase: '',
            tipoPago: '',
            vendedor: '', //new Vendedor(cargo, contacto, nombre, uid),
            cliente: '', //new Cliente('', '','','','','',`T. ${v.turno} | ${horaInicio} - .. : .. : ..`),
            active: false,
            fecha: ''
        }

        newDetallesTurno.turno = detallesTurno.turno;
        newDetallesTurno.inicio = detallesTurno.inicio;
        newDetallesTurno.vendedor = detallesTurno.vendedor;
        newDetallesTurno.cliente = {codigo: '', 
                            contacto: '',
                            correo: '',
                            direccion: '',
                            id: '',
                            nit: '',
                            nombre: `T. ${detallesTurno.turno} | ${detallesTurno.inicio}`
                            };
        newDetallesTurno.active = true;
        newDetallesTurno.fecha = detallesTurno.fecha;

        // GUARDAR EL TURNO EN LA BASE DE DATOS...
        dispatch( startLoading() );

        const refDB = ref( realtime, 'turno/'+detallesTurno.vendedor.uid );
        await set( refDB, {...newDetallesTurno} );

        dispatch(iniciarTurno({...newDetallesTurno}));
        
        dispatch( finishLoading() );
    }
}

export const agregarVentasDB = ( ventas=[], uidVendedor ) => {
    return async(dispatch, getState ) => {
        const { sidebar } = getState( s => s );
        let newDetallesTurno = {...sidebar.detallesTurno};
        newDetallesTurno.ventas = [...newDetallesTurno.ventas, ...ventas];

        // EDITAR EL TURNO EN LA BASE DE DATOS...
        dispatch( startLoading() );

        const refDB = ref( realtime, 'turno/'+uidVendedor );
        await set( refDB, {...newDetallesTurno} );

        dispatch(agregarVentas([...ventas]));
        dispatch( finishLoading() );        
        
    }
}

export const editarVentasDB = (ventas=[], uidVendedor) => {
    //Reemplaza todas las ventas de la base de datos por las nuevas

    return async(dispatch, getState ) => {
        const { sidebar } = getState( s => s );
        let newDetallesTurno = {...sidebar.detallesTurno};
        newDetallesTurno.ventas = [...ventas];

        // EDITAR EL TURNO EN LA BASE DE DATOS...
        dispatch( startLoading() );

        const refDB = ref( realtime, 'turno/'+uidVendedor );
        await set( refDB, {...newDetallesTurno} );

        dispatch(editarVentas([...ventas]));
        dispatch( finishLoading() );        
        
    }
}

export const finalizarTurnoDB = (uid, data) => {
    return async( dispatch ) => {

        // FINALIZAR EL TURNO EN LA BASE DE DATOS...
        dispatch( startLoading() );
        await addDoc( collection( db, '/ventas/registroVentas/ventas' ), data );
        dispatch( agregarNuevaVenta(data) );

        const refDB = ref( realtime, 'turno/'+uid );
        await remove( refDB );

        dispatch( finalizarTurno() );
        dispatch( finishLoading() );

    }
}

export const verificarInicioTurnoDB = (uid) => {
    return async(dispatch) => {
        dispatch( startLoading() );
        const refDB = ref( realtime, 'turno/'+uid );
        
        await get(refDB).then((snapshot) => {
            if( snapshot.exists() ){
                const dataTurno = snapshot.val();
                if( dataTurno.ventas === undefined ){
                    dataTurno.ventas = []
                }
                dispatch(iniciarTurno({...dataTurno}));
                console.log('Turno iniciado con el UID: '+uid);
            }else{
                console.log('No se inicio turno: '+uid);
                dispatch( finalizarTurno() );
            }
        }).catch((error) => {
            console.log(error);
        });

        dispatch( finishLoading() );
    }
}