import { useDispatch, useSelector } from "react-redux"
import { ItemListComprasTurno } from '../components/ItemListComprasTurno';
import { unDecimal } from '../../../helpers/numConfig';
import { useFormList } from "../../../hooks/useFormList";
import { generarFechaAMD } from "../../../helpers/dateConfig";
import { editarVentasDB, finalizarTurnoDB } from "../slice/sidebarThunk";
import { useEffect, useState } from "react";
import { TurnoAlertNotification } from "../components/TurnoAlertNotification";
import { generarIndiceNuevaVenta, refrescarColeccionVentas } from "../../../pages/ventas/slices/ventasThunk";


export const TurnoDetalles = ({ setTurnoDetalles, setDetallesVenta, setVenta }) => {

  const [editMode, setEditMode] = useState(false);
  const [turnoAlertNotification, setTurnoAlertNotification] = useState(false);
  const [fin, setFin] = useState('.. : .. : ..')

  const dispatch = useDispatch();
  const { onLoad, detallesTurno } = useSelector(s => s.sidebar);
  const { uid } = useSelector(s => s.login);
  const { indiceVenta } = useSelector(s => s.ventas);
  const [formValues, handleInputChange,,listDelete,, handleInputChangeManual] = useFormList(detallesTurno.ventas);

  const quitarItem = (index) => {
    if( formValues[index].numeroVentaTitulo && index !== (formValues.length-1) ){
      if( formValues[index].numeroVentaTitulo === formValues[index+1].numeroVenta ){
        const nextIndex = index+1;
        const nextValue = formValues[index].numeroVentaTitulo;
        //Existe otro prducto en el grupo de la venta, asi que le agregamos el campo 'numeroVentaTitulo', ya q se esta eliminando el unico que lo tiene
        handleInputChangeManual('numeroVentaTitulo', nextIndex, nextValue);
      }else{
        console.log('Fue el ultimo Pa T_T');
      }
    }
    
    listDelete(index);
  }

  const guardarTurnoDetalles = () => {
    let precio = generarTotal(); 
    const newVenta = {
      cliente: {...detallesTurno.cliente, nombre: `${detallesTurno.cliente.nombre} - ${fin}`},
      factura: { iva: 0, it: 0, subtotal: precio.total, total: precio.total },
      fecha: detallesTurno.fecha,
      idCliente: detallesTurno.cliente.id,
      items:[...detallesTurno.ventas],
      numero:indiceVenta,
      pagos: [
        {detalle:'', 
        fecha:detallesTurno.fecha, 
        monto:precio.total, 
        usuario:{nombre:detallesTurno.vendedor.nombre, uid:detallesTurno.vendedor.uid}
      }],
      precioBase: 'sin factura',
      tipoPago: 'caja',
      total: precio.total,
      vendedor: {...detallesTurno.vendedor}
    }
    dispatch( finalizarTurnoDB(uid, newVenta) );

    setTimeout(() => {
      setVenta({...newVenta});
      setDetallesVenta(s=>!s);
      setTurnoDetalles(s=>!s);          
    }, 1500);
  }
  
  const guardarEdicion = () => {  
    dispatch( editarVentasDB([...formValues], uid) );
  }

  useEffect(() => {
    const fechaActual = new Date();
    const hora = fechaActual.getHours();
    const minutos = fechaActual.getMinutes();
    const segundos = fechaActual.getSeconds();
    const horaFin = hora + ":" + minutos + ":" + segundos; 
    setFin( horaFin ); 

    // dispatch( refrescarColeccionVentas() );
    dispatch( generarIndiceNuevaVenta() );
  }, [])
  
  
  const generarTotal = () => {
    let precio = {
        iva: 0,
        it: 0,
        subtotal: 0,
        total: 0
    }
    formValues.forEach(c => {
        precio.total += (c.cantVenta * c.precioVenta);          
    });
    precio.iva = (precio.total*13)/100; // IVA es el 13%
    precio.it = (precio.total*3)/100; // IVA es el 3%
    precio.subtotal = precio.total - precio.iva - precio.it;

    return unDecimal(precio)
  }
  return (
  <div className='window'>

    {/* VENTANAS */}
    {turnoAlertNotification&&
      <TurnoAlertNotification
        setTurnoAlertNotification={setTurnoAlertNotification}
        titulo={'FINALIZANDO TURNO'}
        mensaje={
        <>
          <p className="m-0" >El turno se finalizara guardando el detalle en la lista de las ventas.</p>
          <p>¿Estas seguro de finalizar el turno?</p>
        </>}
        funcion={guardarTurnoDetalles}
      />
    }

    <div className="window-container">
      <div className="window-head">
        <span> VENTA Nº {indiceVenta} | VENTAS DEL TURNO</span>
        <div className="btn-exit" onClick={() => {setTurnoDetalles(s => !s)}} >
            <i className="bi bi-x"></i>
        </div>
      </div>
      <div className="window-body">
        <div className="container">
          <div className="row text-dark">
            <div className="col-6">
              <p><span className="fw-bold" >Nombre: </span>{detallesTurno.vendedor.nombre}</p>
              <p><span className="fw-bold" >Descripcion: </span>{detallesTurno.cliente.nombre} - {fin}</p>
              <p><span className="fw-bold" >Fecha: </span>{ generarFechaAMD(detallesTurno.fecha) }</p>
            </div>
            <div className="col-6">
              <p><span className="fw-bold" >Inicio de turno: </span>{detallesTurno.inicio}</p>
              <p><span className="fw-bold" >Fin de turno: </span>{fin}</p>
            </div>
          </div>
        </div>

        <table className="table table-hover" >
            <thead>
                <tr>
                    <th scope="col">#</th>
                    <th scope="col">Modelo</th>
                    <th scope="col">Nombre</th>
                    <th scope="col">Marca</th>
                    <th scope="col">Medida</th>
                    <th scope="col">Cantidad</th>
                    <th scope="col">P/Base</th>
                    <th scope="col">P/Unit</th>
                    <th scope="col">Total</th>
                </tr>
            </thead>
            <tbody className="table-group-divider" >
                {formValues.map((c, index) =>(
                  <ItemListComprasTurno 
                  key={index} 
                  c={c} 
                  index={index} 
                  handleInputChange={handleInputChange} 
                  quitarItem = {quitarItem}
                  editMode={editMode}
                  />
                ))
                }
                <tr className='fw-bold h5' >
                    <td colSpan='8' className='text-end' >TOTAL</td>
                    <td colSpan='2' className='text-start'>
                    {generarTotal().total} Bs.
                    </td>
                </tr>
            </tbody>
        </table>
      </div>

      <div className="window-footer">
        <div className="container-fluid">
          <div className="row pe-2 ">
              <div className="col d-flex justify-content-end mb-2">

                  {editMode?
                  <>
                    <button 
                    className="btn btn-success" 
                    disabled = {onLoad}
                    onClick={guardarEdicion}
                    >
                        {onLoad&&
                        <div className="spinner-border spinner-border-sm text-white me-2" role="status">
                            <span className="visually-hidden">Loading...</span>
                        </div>
                        }
                        Guardar cambios
                    </button>

                    <button
                    className="btn btn-secondary ms-3"
                    onClick={() => { setEditMode(false) }}
                    >
                      Dejar de editar
                    </button>
                  </>
                  :
                  <>
                    <button
                    disabled = {onLoad}
                    className="btn btn-danger ms-3"
                    onClick={() => { setTurnoAlertNotification(s=>!s) }}
                    >
                      {onLoad&&
                        <div className="spinner-border spinner-border-sm text-white me-2" role="status">
                            <span className="visually-hidden">Loading...</span>
                        </div>
                      }
                      Finalizar turno
                    </button>

                    <button
                    disabled = {onLoad}
                    className="btn btn-secondary ms-3"
                    onClick={() => { setEditMode(true) }}
                    >
                      Editar
                    </button>
                  </>
                  }
                
              </div>
          </div>
        </div>
      </div>
    </div>
  </div>
  )
}
