import { useDispatch, useSelector } from 'react-redux';
import { unDecimal } from '../../../helpers/numConfig';
import { ItemListComprasTurno } from '../components/ItemListComprasTurno';
import { disminuirCantidadItem } from '../../../pages/productos/slices/productosThunk';
import { obtenerColeccionVentas } from '../../../pages/ventas/slices/ventasThunk';
import { agregarVentasDB } from '../slice/sidebarThunk';
import { startLoading } from '../slice/sidebarSlice';


export const TurnoAgregarCompras = ({ setTurnoDetallesCompras, listCompras, handleInputChange, quitarItem, listComprasReset }) => {

    const dispatch = useDispatch();
    const { uid } = useSelector(s => s.login);
    const { onLoad, numeroVenta, detallesTurno } = useSelector(s => s.sidebar);
  
    const agregarVentaTurno = async () => {
        dispatch( startLoading() );
        //Disminuye las cantidades vendidas del almacen
        listCompras.forEach(item => {
            item.numeroVenta = numeroVenta+1;//Para verificar a que grupo de ventas pertenece
            const ubicacion = `/aplicaciones/productos/items/${ item.id }`; 
            dispatch( disminuirCantidadItem( ubicacion, item ) );
        });
        listCompras[0].numeroVentaTitulo = numeroVenta+1; //Para poner un titulo en las tablas
        //Actualizamos los items
        setTimeout(() => {
            dispatch(obtenerColeccionVentas());
            dispatch( agregarVentasDB([...listCompras], uid) );
            listComprasReset();
            setTurnoDetallesCompras(s => !s)
        }, 1500);
    }
   
    const generarTotal = () => {
        let precio = {
            iva: 0,
            it: 0,
            subtotal: 0,
            total: 0
        }
        listCompras.forEach(c => {
            precio.total += (c.cantVenta * c.precioVenta);          
        });
        precio.iva = (precio.total*13)/100; // IVA es el 13%
        precio.it = (precio.total*3)/100; // IVA es el 3%
        precio.subtotal = precio.total - precio.iva - precio.it;

        return unDecimal(precio)
    }

  return (
    <div className='window'>
        <div className="window-container">
            <div className="window-head">
                <span> TURNO {detallesTurno.turno} - VENTA Nº{numeroVenta+1} </span>
                <div className="btn-exit" onClick={() => {setTurnoDetallesCompras(s => !s)}} >
                    <i className="bi bi-x"></i>
                </div>
            </div>
            <div className="window-body">
                <table className="table table-hover" >
                    <thead>
                        <tr>
                            <th scope="col">#</th>
                            <th scope="col">Modelo</th>
                            <th scope="col">Nombre</th>
                            <th scope="col">Marca</th>
                            <th scope="col">Medida</th>
                            <th scope="col">Cantidad</th>
                            <th scope="col">P/Base</th>
                            <th scope="col">P/Unit</th>
                            <th scope="col">Total</th>
                        </tr>
                    </thead>
                    <tbody className="table-group-divider" >
                        {listCompras.map((c, index) => (
                            <ItemListComprasTurno 
                            key={index} 
                            c={c} 
                            index={index} 
                            handleInputChange={handleInputChange} 
                            quitarItem = {quitarItem} />
                        ))
                        }
                        <tr className='fw-bold h5' >
                            <td colSpan='8' className='text-end' >TOTAL</td>
                            <td colSpan='2' className='text-start'>
                             {generarTotal().total} Bs.
                            </td>
                        </tr>
                    </tbody>
                </table>

                <div className="row">
                    <div className="col d-flex justify-content-center mb-2">
                        <button 
                        className="btn btn-success" 
                        onClick={agregarVentaTurno}
                        disabled = {onLoad}
                        >
                            {onLoad&&
                            <div className="spinner-border spinner-border-sm text-white me-2" role="status">
                                <span className="visually-hidden">Loading...</span>
                            </div>
                            }
                            Agregar</button>
                    </div>
                </div>
            </div>
        </div>
    </div>
  )
}
