import { useState } from "react";
import { useRef } from "react";
import { useEffect } from "react";
import { useDispatch, useSelector } from "react-redux";
import { ItemListVenta } from "../components/ItemListVenta";
import { resetBusquedaCliente } from "../slices/ventasSlice";
import { buscarColeccionListaVentasPorNumero, obtenerColeccionListaVentasPorFecha } from "../slices/ventasThunk";
import { BuscarCliente } from "./BuscarCliente";
import { ReporteVentas } from "./ReporteVentas";
import { VistaPdfVentas } from "./VistaPdfVentas";


export const ListVentas = ({ setListVentas }) => {
    const vendedores = new Set();
    const date = new Date();
    const primer = new Date(date.getFullYear(), date.getMonth(), 1);
    const primerDia = primer.toISOString().split('T')[0];
    const ultimo = new Date(date.getFullYear(), date.getMonth() + 1, 0);
    const ultimoDia = ultimo.toISOString().split('T')[0];
    const dispatch = useDispatch();
    const { registroVentas, actualizandoDatos, busquedaCliente } = useSelector(s => s.ventas);

    const inputFechaIni = useRef();
    const inputFechaFin = useRef();

    const inputFechaIniM = useRef();
    const inputFechaFinM = useRef();

    const inputNumero = useRef();
    const [nombreCliente, setNombreCliente] = useState('');
    const [tipoPago, setTipoPago] = useState('');
    const [deuda, setDeuda] = useState(0);
    const [reporteVentas, setReporteVentas] = useState(false);
    const [buscarCliente, setBuscarCliente] = useState(false);
    const [vistaPdfVentas, setVistaPdfVentas] = useState(false);
    const [vendedorSelected, setVendedorSelected] = useState("");

    const generarSaldo = (pagos) => {
        let saldo = 0;
        pagos.forEach(p => {
            saldo += parseFloat(p.monto);
        });
        return saldo;
    }

    const showRegistroVentas = registroVentas.filter(i => {
        vendedores.add(i.vendedor.nombre)
        if (i.tipoPago.toLowerCase().includes(tipoPago) && (i.vendedor.nombre.includes(vendedorSelected)) && ((i.total - generarSaldo(i.pagos)) >= deuda)) {
            if (busquedaCliente.cliente.codigo) {
                if (i.idCliente === busquedaCliente.cliente.codigo) {
                    return i;
                }
            }
            else {
                if (i.cliente?.nombre.toLowerCase().includes(nombreCliente)) return i;
            }
        }
    });

    const listaVendedores = Array.from(vendedores);

    const filtrarTipoPago = ({ target }) => {
        setTipoPago(target.value);
    }

    const buscarPorFecha = () => {
        const i = inputFechaIni.current.value;
        const f = inputFechaFin.current.value;

        if (i !== '' || f !== '') {
            dispatch(obtenerColeccionListaVentasPorFecha(i, f));
        }
    }
    const buscarPorFechaM = () => { //Funcion para filtrar en mobil
        const i = inputFechaIniM.current.value;
        const f = inputFechaFinM.current.value;

        if (i !== '' || f !== '') {
            dispatch(obtenerColeccionListaVentasPorFecha(i, f));
        }
    }

    const buscarPorNumero = () => {
        const num = parseInt(inputNumero.current.value);
        if (num !== '') {
            dispatch(buscarColeccionListaVentasPorNumero(num));
        }
    }

    const resetSearch = () => {
        setNombreCliente('');
        dispatch(resetBusquedaCliente())
    }


    useEffect(() => {
        dispatch(obtenerColeccionListaVentasPorFecha(primerDia, ultimoDia));
    }, []);
    return (
        <div className='window'>
            {/* VENTANAS */}
            {reporteVentas &&
                <ReporteVentas
                    setReporteVentas={setReporteVentas}
                    tipoPago={tipoPago}
                />
            }
            {buscarCliente &&
                <BuscarCliente setBuscarCliente={setBuscarCliente} />
            }
            {vistaPdfVentas &&
                <VistaPdfVentas
                    setVistaPdfVntas={setVistaPdfVentas}
                    showRegistroVentas={showRegistroVentas}
                    primerDia={primerDia}
                    ultimoDia={ultimoDia}
                />
            }

            <div className="window-container">
                <div className="window-head">
                    <span>LISTA DE VENTAS</span>
                    <div className="btn-exit" onClick={() => {
                        setListVentas(s => !s);
                        dispatch(resetBusquedaCliente());
                    }} >
                        <i className="bi bi-x"></i>
                    </div>
                </div>
                <div className="container-fluid">
                    <div className="row my-3">
                        <div className="col-12 col-md-6 d-flex mb-2 mb-md-0">
                            <div className="col-1 me-1 me-md-0">
                                <input
                                    type='number'
                                    placeholder="#"
                                    className="form-control form-control-sm"
                                    ref={inputNumero}
                                />
                            </div>
                            <div className="col-md-2 mx-md-1">
                                <button
                                    type='button'
                                    className={actualizandoDatos ? 'btn btn-primary disabled' : 'btn btn-primary'}
                                    onClick={buscarPorNumero}
                                >
                                    {actualizandoDatos &&
                                        <div className="spinner-border spinner-border-sm text-white me-2" role="status">
                                            <span className="visually-hidden">Loading...</span>
                                        </div>
                                    }
                                    Buscar
                                </button>
                            </div>

                            <div className="ms-auto ms-md-0 me-1 me-md-0 col-md-3 me-md-2">
                                <select
                                    className="form-select form-select-sm"
                                    onChange={filtrarTipoPago}
                                >
                                    <option value=''>Tipo de Pago</option>
                                    <option value="efectivo">Efectivo</option>
                                    <option value="caja">Caja</option>
                                    <option value="banco">Banco</option>
                                    <option value="credito">Credito</option>
                                </select>
                            </div>
                            <div className="col-md-3">
                                {(deuda === 0) ?
                                    <div className="btn btn-success"
                                        onClick={() => { setDeuda(1) }}
                                    >Deudores</div>
                                    :
                                    <div className="btn btn-secondary"
                                        onClick={() => { setDeuda(0) }}
                                    >Todos</div>
                                }
                            </div>

                        </div>
                        <div className="col-12 col-md-6 d-none d-md-flex justify-content-end">
                            <label className='fw-bold text-end pe-2' htmlFor="fechaInicio"> Fecha inicial: </label>
                            <div className='me-1' >
                                <input
                                    style={{ width: '80%' }}
                                    type="date"
                                    className='form-control form-control-sm py-1'
                                    autoComplete='off'
                                    id='fechaInicio'
                                    name='fechaInicio'
                                    defaultValue={primerDia}
                                    ref={inputFechaIni}
                                />
                            </div>
                            <label className='fw-bold text-end pe-2' htmlFor="fechaFinal"> Fecha final: </label>
                            <div className='me-1'>
                                <input
                                    style={{ width: '80%' }}
                                    type="date"
                                    className='form-control form-control-sm py-1'
                                    autoComplete='off'
                                    id='fechaFinal'
                                    name='fechaFinal'
                                    defaultValue={ultimoDia}
                                    ref={inputFechaFin}
                                />
                            </div>


                            <div className=' d-flex justify-content-end' >
                                <button
                                    type='button'
                                    className={actualizandoDatos ? 'btn btn-primary disabled' : 'btn btn-primary'}
                                    onClick={buscarPorFecha}
                                >
                                    {actualizandoDatos &&
                                        <div className="spinner-border spinner-border-sm text-white me-2" role="status">
                                            <span className="visually-hidden">Loading...</span>
                                        </div>
                                    }
                                    Filtrar
                                </button>
                            </div>
                        </div>

                        {/* --------------------------  DISPOSITIVO MOBIL ------------------- */}

                        <div className="col-12 col-md-6 d-md-none d-flex">
                            <div className='col-4'>
                                <input
                                    type="date"
                                    className='form-control form-control-sm py-1'
                                    autoComplete='off'
                                    id='fechaInicioM'
                                    name='fechaInicioM'
                                    defaultValue={primerDia}
                                    ref={inputFechaIniM}
                                />
                            </div>

                            <div className="mx-3" ><span className="fw-bold" >-</span></div>

                            <div className='col-4'>
                                <input
                                    style={{ width: '90%' }}
                                    type="date"
                                    className='form-control form-control-sm py-1'
                                    autoComplete='off'
                                    id='fechaFinalM'
                                    name='fechaFinalM'
                                    defaultValue={ultimoDia}
                                    ref={inputFechaFinM}
                                />
                            </div>


                            <div className='ms-auto d-flex justify-content-end' >
                                <button
                                    type='button'
                                    className={actualizandoDatos ? 'btn btn-primary disabled' : 'btn btn-primary'}
                                    onClick={buscarPorFechaM}
                                >
                                    {actualizandoDatos &&
                                        <div className="spinner-border spinner-border-sm text-white me-2" role="status">
                                            <span className="visually-hidden">Loading...</span>
                                        </div>
                                    }
                                    Filtrar
                                </button>
                            </div>
                        </div>
                        {/* --------------------------  DISPOSITIVO MOBIL ------------------- */}


                    </div>
                    {/* ENCABEZADO */}
                    <div className="row bg-primary text-white fw-bold">
                        <div className="col-1 col-md-1">
                            <p className="m-0 text-center" >#</p>
                        </div>
                        <div className="col-3 col-md-2">
                            <p className="m-0 text-center" >FECHA</p>
                        </div>
                        <div className="col-6 col-md-2">
                            <p className="m-0 text-center" >CLIENTE</p>
                        </div>
                        <div className="col-md-1 d-none d-md-block">
                            <p className="m-0 text-center" >PAGO</p>
                        </div>
                        <div className="col-md-1 d-none d-md-block">
                            <p className="m-0 text-center" >PAGADO</p>
                        </div>
                        <div className="col-md-1 d-none d-md-block">
                            <p className="m-0 text-center" >RESTANTE</p>
                        </div>
                        <div className="col-md-1 d-none d-md-block">
                            <p className="m-0 text-center" >IVA</p>
                        </div>
                        <div className="col-md-1 d-none d-md-block">
                            <p className="m-0 text-center" >IT</p>
                        </div>
                        <div className="col-md-1 d-none d-md-block">
                            <p className="m-0 text-center" >TOTAL</p>
                        </div>
                        <div className="col-2 col-md-1">
                            <p className="m-0 text-center" >MAS</p>
                        </div>
                    </div>
                </div>

                <div className="window-body">
                    <div className="container-fluid">
                        {(showRegistroVentas.length <= 0) &&
                            <div className="row">
                                <div className="col">
                                    <p className="text-muted text-center" >No se encontro ningun registro de ventas...</p>
                                </div>
                            </div>
                        }
                        {showRegistroVentas.map((v, index) => (
                            <ItemListVenta key={index} venta={v} />
                        ))}
                    </div>
                </div>


                <div className="window-footer">
                    {busquedaCliente.cliente.nombre ?
                        <>
                            <div className="d-flex justify-content-center align-items-center">
                                <span className="me-2 fw-bold" > Compras de {busquedaCliente.cliente.nombre}</span>
                            </div>
                            <div className="d-flex justify-content-center align-items-center">
                                <div className="btn-icon-danger-sm" onClick={resetSearch} > <i className="bi bi-x-lg"></i> </div>
                            </div>
                        </>
                        :
                        <>
                            <div className='input-search col-3 ' >
                                <input
                                    type="search"
                                    placeholder='Nombre de cliente...'
                                    autoComplete='off'
                                    onChange={(e) => { setNombreCliente(e.target.value) }}
                                />
                                <i className="bi bi-search" style={{ left: '15px' }} ></i>
                            </div>
                        </>
                    }
                    <div className="flex gap-2 ms-2 me-auto">
                        <select
                            className="form-select form-select-sm"
                            onChange={(e) => setVendedorSelected(e.target.value)}
                        >
                            <option value="">-- Elige un vendedor --</option>

                            {listaVendedores.map((vendedor) => (
                                <option key={vendedor} value={vendedor}>
                                    {vendedor}
                                </option>
                            ))}
                        </select>
                    </div>
                    <div className="d-flex justify-content-center align-items-center me-3">
                        <div className="btn-icon-primary-outline" onClick={() => { setVistaPdfVentas(!vistaPdfVentas) }} ><i className="bi bi-cloud-arrow-down-fill"></i></div>
                    </div>
                    <div className="btn btn-primary me-3" onClick={() => { setBuscarCliente(!buscarCliente) }} >
                        <span className="d-none d-md-block" >Filtrar cliente</span>
                        <span className="d-md-none" >Clientes</span>
                    </div>


                    <div className="btn btn-secondary" onClick={() => { setReporteVentas(!reporteVentas) }} >
                        <span className="d-none d-md-block">Reporte de ventas</span>
                        <span className="d-md-none">Reporte</span>
                    </div>
                </div>
            </div>
        </div>
    )
}
