import { useState } from 'react';
import { EditarItem } from './EditarItem';

export const ProductosItem = ({item}) => {

    const { imgUrl, modelo,marca, nombre, cantidad } = item;
    const [activeItemEdition, setActiveItemEdition] = useState(false);

  return (
    <div className="acordeon-item">
        <div className="container-fluid p-0">
            <div className="row">
                {/* IMAGEN */}
                <div className="col-3 col-md-2 d-flex justify-content-center align-items-center ">
                    <div 
                        className='d-flex justify-content-center align-items-center rounded' 
                        style={{width:'160px', height:'110px', overflow:'hidden' }} 
                    >
                        <img loading='lazy' src={imgUrl}  style={{ width:'auto', height:'110px' }} />
                    </div>
                </div>
                
                {/* MODELO */}
                <div className="col-2 col-md-2 d-flex justify-content-center align-items-center ">{modelo.toUpperCase()}</div>

                {/* MARCA */}
                <div className="col-3 col-md-1 d-flex justify-content-center align-items-center ">{marca.toUpperCase()}</div>

                {/* NOMBRE */}
                <div className="col-md-5 d-none d-md-flex justify-content-center align-items-center ">{nombre.toUpperCase()}</div>

                {/* CANTIDAD */}
                <div className="col-2 col-md-1 d-flex justify-content-center align-items-center ">{cantidad}</div>


                {/* MAS */}
                <div className="col-2 col-md-1 d-flex justify-content-center align-items-center ">
                    <button 
                    className='btn-icon-white' 
                    onClick={()=>{ setActiveItemEdition(!activeItemEdition) }}
                    > 
                        <i className="bi bi-three-dots"></i> 
                    </button>
                </div>
            </div>

        {activeItemEdition&&
            <EditarItem item = {item} activeItemEdition={activeItemEdition} setActiveItemEdition={setActiveItemEdition}/>}
        </div>

    </div>
  )
}
