import React, { useEffect, useRef } from 'react';
import { generarFechaHoraISOS } from '../../../helpers/dateConfig';
import { editarConfiguracion, } from '../slices/ventasSlice';
import { unDecimal } from '../../../helpers/numConfig';
import { BuscarCliente } from '../windows/BuscarCliente';
import { useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { upperCamelCase } from '../../../helpers/textConfig';

export const FormNuevaCotizacion = ({handleInputChangeObj, valueManual, cliente, contacto, handleInputChange, handleInputChangeManual, formValues, listDelete, listItems, setListItems, inputFecha, inputOferta}) => {
    const dispatch = useDispatch();
    
    const { precios } = useSelector( s => s.productos );
    const { configuracion, busquedaCliente } = useSelector( s => s.ventas );
    
    const precioBase = useRef();
    
    const [buscarCliente, setBuscarCliente] = useState(false);
    // const [ datosAnteriores, setDatosAnteriores ] = useState({ cliente, contacto });
    // console.log( buscarCliente.encontrado );

    const eliminarEspacio = (index, id) => {
        listDelete(index, id);
        const newListItems = listItems.map(i => {
            if(i.id === id) i.select = false;
            return i
        });
        setListItems(newListItems);
    }
    const cambiarPrecio = ({target}) => {
        formValues.forEach((c, index) => {
            const newPrecio = c.precios[target.value] || 0;
            handleInputChangeManual( 'precio', index, newPrecio );
        });
        dispatch( editarConfiguracion( {precioBase: target.value} ) );
    }

    useEffect(() => {

        if(busquedaCliente.encontrado){
            valueManual({ cliente: busquedaCliente.cliente.nombre, contacto: busquedaCliente.cliente.contacto});
        }else{
            valueManual({ cliente: '', contacto: '' });
        }
    }, [ busquedaCliente ]);

  return (
    <>

    {/* WINDOWS */}
    {buscarCliente&&
        <BuscarCliente setBuscarCliente={ setBuscarCliente } />
    }


    <div className="row mb-md-3">
        <div className="col-12 col-md-4 text-start">
            <label className='fw-bold'  htmlFor="cliente"> Cliente: </label> 
            <span 
            className='text-primary fw-normal ms-2' 
            style={{ cursor:'pointer' }}
            onClick={() => { setBuscarCliente(!buscarCliente) }} 
            > Buscar cliente...
            </span> 
            <input 
                type="text" 
                className='form-control py-1'
                placeholder='Nombre del cliente'
                autoComplete='off'
                id='cliente'
                name='cliente'
                onChange={handleInputChangeObj}
                value={cliente}
                required
            />
        </div>
        <div className="col-6 col-md-2 text-start">
            <label className='fw-bold'  htmlFor="contacto"> Contacto: </label>
            <input 
                type="number" 
                className='form-control py-1'
                placeholder='Número de contacto'
                autoComplete='off'
                id='contacto'
                name='contacto'
                onChange={handleInputChangeObj}
                value={contacto}
            />
        </div>
        <div className="col-6 col-md-2">
            <label className='fw-bold' htmlFor="precioBase"> Precio base: </label>
            <select 
            className="form-select py-1"
            id='precioBase'
            name='precioBase'
            ref={precioBase}
            onChange={ cambiarPrecio }
            value={ configuracion.precioBase }
            >
                {
                precios.map( p => (
                    <option key={p.id} value={p.tipo}>{ upperCamelCase( p.tipo )}</option>
                ) )
                }
            </select>         
        </div> 
        <div className="col-6 col-md-2 text-start">
            <label className='fw-bold' htmlFor="fecha"> Fecha: </label>
            <input 
                type="datetime-local" 
                className='form-control py-1'
                autoComplete='off'
                id='fecha'
                name='fecha'
                defaultValue={ generarFechaHoraISOS(Date.now()) }
                ref={inputFecha}
            />
        </div>
        <div className="col-6 col-md-2 text-start">
            <label className='fw-bold' htmlFor="fecha"> Días de oferta: </label>
            <input 
                type="number" 
                className='form-control py-1'
                autoComplete='off'
                id='oferta'
                name='oferta'
                defaultValue={5}
                ref={inputOferta}
            />
        </div>
        <hr className='d-block d-md-none my-4 border border-secondary border-1 opacity-100' />
    </div>

    <div className="d-none d-md-flex row px-2 mb-2">
        <div className="col-5 px-1 fw-bold text-start">
            DESCRIPCION
        </div>
        <div className="col-2 px-1 fw-bold text-start">
            MARCA
        </div>
        <div className="col px-1 fw-bold text-start">
            MODELO
        </div>
        <div className="col px-1 fw-bold text-start">
            CANTIDAD
        </div>
        <div className="col px-1 fw-bold text-start">
            P UNIT.
        </div>
        <div className="col px-1 fw-bold text-start">
            SUBTOTAL
        </div>
        <div style={{ width: '30px' }}>
            {/* NO BORRAR */}
            {/* ESPACIO DEL BOTON ELIMINAR */}
        </div>
    </div>

    {formValues.map((obj, index)=>(
        <div key={index} className="row mb-2 px-2">
            <div className="mb-2 mb-md-0 col-8 col-md-5 px-1">
                <input 
                className='form-control py-1' 
                type="text" 
                autoComplete='off'
                placeholder='Descripcion...'
                name= {`nombre_${index}`}
                onChange={handleInputChange}
                value={obj.nombre}
                required
                />
            </div>

            <div className="mb-2 mb-md-0 col-4 col-md-2 px-1">
                <input 
                className='form-control py-1' 
                type="text" 
                autoComplete='off'
                placeholder='Marca...'
                name= {`marca_${index}`}
                onChange={handleInputChange}
                value={obj.marca}
                />
            </div>
            
            <div className="col px-1">
                <input 
                className='form-control py-1' 
                type="text" 
                autoComplete='off'
                placeholder='Modelo...'
                name= {`modelo_${index}`}
                onChange={handleInputChange}
                value={obj.modelo}
                />
            </div>

            <div className="col px-1">
                <input 
                className='form-control py-1' 
                type="number" 
                autoComplete='off'
                placeholder='Cantidad...'
                name= {`cantidad_${index}`}
                onChange={handleInputChange}
                value={obj.cantidad}
                required
                />
            </div>

            <div className="col px-1">
                <input 
                className='form-control py-1' 
                type="number"  
                step="0.0001"             
                autoComplete='off'
                placeholder='Precio...'
                name= {`precio_${index}`}
                onChange={handleInputChange}
                value={obj.precio}
                // value={obj.precio}
                required
                />
            </div>
            <div className="col px-1">
                <p className=' text-end fw-bold m-0 ' > { unDecimal(obj.cantidad * obj.precio) } Bs. </p>
            </div>

            <div 
            className="col-1 btn-icon-danger"
            onClick={()=>{eliminarEspacio(index, obj.id)}}
            >
                <i className="bi bi-trash-fill"></i>
            </div>

            <hr className='d-block d-md-none mt-2 opacity-75' />
        </div>
    ))}


    </>
  )
}
