import { generarFechaDMA, generarFechaHoraAMD } from "../../../helpers/dateConfig";
import { upperCamelCase } from "../../../helpers/textConfig";
import logo from '../../../assets/svg/logo-letra.svg';
import { useEffect, useRef, useState } from "react";
import { pdfVistaPdfVentas } from "../pdf/pdfVistaPdfVentas";
import * as XLSX from 'xlsx';

export const VistaPdfVentas = ({ setVistaPdfVntas, showRegistroVentas, primerDia, ultimoDia }) => {

  const table = useRef();
  const [registroVentas, setRegistroVentas] = useState([]);
  const [registroTotales, setRegistroTotales] = useState({ pagado: 0, restante: 0, iva: 0, it: 0, total: 0 });

  const generarSaldo = (pagos) => {
    let saldo = 0;
    pagos.forEach(p => {
      saldo += parseFloat(p.monto);
    });
    return saldo;
  }
  const generarTotal = () => {
    let totales = {
      iva: 0,
      it: 0,
      total: 0,
      pagado: 0,
      restante: 0
    }

    showRegistroVentas.forEach(v => {
      totales.iva += v.factura ? v.factura.iva : 0;
      totales.it += v.factura ? v.factura.it : 0;
      totales.pagado += generarSaldo(v.pagos);
      totales.restante += v.total - generarSaldo(v.pagos);
      totales.total += v.total;
    });

    return (totales)
  }

  const descargarVistaPdfVentas = () => {
    const id = table.current.id;
    const datos = {
      fechaInicial: generarFechaDMA(primerDia),
      fechaFinal: generarFechaDMA(ultimoDia)
    }
    pdfVistaPdfVentas(id, datos);
  }

  const descargarExcel = () => {
    const libro = XLSX.utils.book_new();
    const hoja = XLSX.utils.json_to_sheet(registroVentas);
    XLSX.utils.sheet_add_aoa(hoja, [
      ["COD", "FECHA", "CLIENTE", "PAGO", "PAGADO", "RESTANTE", "IVA", "IT", "TOTAL"]
    ], { origin: "A1" });
    XLSX.utils.sheet_add_aoa(hoja, [
      ["TOTAL", null, null, null, registroTotales.pagado, registroTotales.restante, registroTotales.iva, registroTotales.it, registroTotales.total]
    ], { origin: -1 });
    const ultimaFilaIdx = registroVentas.length + 1;
    if (!hoja['!merges']) hoja['!merges'] = [];
    hoja['!merges'].push({
      s: { r: ultimaFilaIdx, c: 0 },
      e: { r: ultimaFilaIdx, c: 3 }
    });

    XLSX.utils.book_append_sheet(libro, hoja, "ventas");
    XLSX.writeFile(libro, "Reporte_ventas.xlsx");
  };

  useEffect(() => {
    const newDatos = showRegistroVentas.map(venta => ({
      cod: venta.numero,
      fecha: generarFechaHoraAMD(venta.fecha),
      cliente: venta.cliente.nombre,
      pago: venta.tipoPago.toUpperCase(),
      pagado: Number(generarSaldo(venta.pagos).toFixed(2)) || 0,
      restante: Number((venta.total - generarSaldo(venta.pagos)).toFixed(2)) || 0,
      iva: Number((venta.factura ? venta.factura.iva : 0).toFixed(2)) || 0,
      it: Number((venta.factura ? venta.factura.it : 0).toFixed(2)) || 0,
      total: Number((venta.total).toFixed(2)) || 0
    }));

    const newTotales = {
      pagado: Number(generarTotal().pagado.toFixed(2)),
      restante: Number(generarTotal().restante.toFixed(2)),
      iva: Number(generarTotal().iva.toFixed(2)),
      it: Number(generarTotal().it.toFixed(2)),
      total: Number(generarTotal().total.toFixed(2)),
    }
    setRegistroTotales(newTotales)
    setRegistroVentas(newDatos);
  }, [])

  return (
    <div className='window'>
      <div className="window-container">
        <div className="window-head">
          <span>VISTA DE VENTAS</span>
          <div className="btn-exit" onClick={() => { setVistaPdfVntas(s => !s) }} >
            <i className="bi bi-x"></i>
          </div>
        </div>

        <div className="window-body">
          <div className="container-fluid">
            <div className="row">
              <div className="col-12 col-md-6">
                <img src={logo} style={{ height: '80px' }} />
              </div>
              <div className="col-12 col-md-6">
                <p> <span className="fw-bold"> Desde: </span> {generarFechaDMA(primerDia)}</p>
                <p> <span className="fw-bold"> Hasta: </span> {generarFechaDMA(ultimoDia)}</p>
              </div>
            </div>

            <div className="view-horizontal" >
              <table className="table table-hover" id="tableVistaPdfVentas" ref={table} >
                <thead>
                  <tr>
                    <th>COD</th>
                    <th>FECHA</th>
                    <th>CLIENTE</th>
                    <th>PAGO</th>
                    <th>PAGADO</th>
                    <th>RESTANTE</th>
                    <th>IVA</th>
                    <th>IT</th>
                    <th>TOTAL</th>
                  </tr>
                </thead>
                <tbody>
                  {registroVentas.map((venta, index) => (
                    <tr key={index} >
                      <td>{venta.cod}</td>
                      <td>{venta.fecha}</td>
                      <td>{venta.cliente}</td>
                      <td>{venta.pago}</td>
                      <td>{venta.pagado} Bs.</td>
                      <td>{venta.restante} Bs.</td>
                      <td>{venta.iva} Bs.</td>
                      <td>{venta.it} Bs.</td>
                      <td>{venta.total} Bs.</td>
                    </tr>
                  ))}
                </tbody>
                <tfoot>
                  <tr>
                    <th colSpan='4' >TOTAL</th>
                    <th>{registroTotales.pagado}Bs.</th>
                    <th>{registroTotales.restante}Bs.</th>
                    <th>{registroTotales.iva}Bs.</th>
                    <th>{registroTotales.it}Bs.</th>
                    <th>{registroTotales.total}Bs.</th>
                  </tr>
                </tfoot>
              </table>
            </div>
          </div>
        </div>

        <div className="window-footer d-flex gap-2">
          <div className="btn btn-success d-flex gap-2" onClick={descargarExcel} ><i className="bi bi-file-earmark-excel-fill"></i>Excel</div>
          <div className="btn btn-danger d-flex gap-2" onClick={descargarVistaPdfVentas} ><i className="bi bi-file-earmark-pdf-fill"></i>PDF</div>
        </div>
      </div>
    </div>
  )
}
