import { useDispatch, useSelector } from "react-redux"
import { tipoOracion } from "../../../../helpers/textConfig";
import { useEffect } from "react";
import { useFormList } from "../../../../hooks/useFormList";
import { editarDocumentoFirebase } from "../../slices/productosThunk";

export const ConfigurarPrecios = ({item, setConfigurarPrecios}) => {
    const dispatch = useDispatch();
    const { precios, actualizandoDatos, actualizacionExitosa } = useSelector(s => s.productos);
    const [formValues, handleInputChange,,,,,listAddArray ] = useFormList([]);


    const guardarConfiguracion = (e) => {
        e.preventDefault();
        const configuracionPrecios =  {auto: true, porcentage:{}};
        const porcentage = {};
        //Crea un Obj = {tipo: porcentage}
        formValues.forEach(v => {
            porcentage[v.tipo] = v.porcentage? parseInt(v.porcentage):0;
        });
        
        configuracionPrecios.porcentage = porcentage;
        const {id, ...itemUpdate} = item;
        const ubicacion = `/aplicaciones/productos/items/${id}`;
        itemUpdate.configuracionPrecios = {...configuracionPrecios}
        dispatch( editarDocumentoFirebase( ubicacion, itemUpdate ) );     
    }

    useEffect(() => {
        let newTipoPrecios = [];
        if(item.configuracionPrecios){
            newTipoPrecios = precios.map(p=>({tipo: p.tipo, porcentage: item.configuracionPrecios.porcentage[p.tipo] || 0}));
        }else{
            // Crea un arreglo de objetos {tipo, porcentage}
            newTipoPrecios = precios.map(p=>({tipo: p.tipo, porcentage: 0})); 
        }

        listAddArray(newTipoPrecios);
    }, [])
  return (
    <div className='window'>
        <div className="window-container-sm">
            <div className="window-head">
                <span>CONFIGURAR PRECIOS</span>
                <div className="btn-exit" onClick={ () => { setConfigurarPrecios(s=>!s) } } >
                    <i className="bi bi-x"></i>
                </div>
            </div>

            <form onSubmit={guardarConfiguracion} >
                <div className="window-body px-5 py-4">
                    {formValues.map((p,i)=>(
                        <div key={i} className="d-flex mb-2">
                            <div className="col-5">
                                <label htmlFor={`porcentage_${i}`}>
                                    {tipoOracion(p.tipo)}
                                </label>
                            </div>
                            <div className="col-2">
                                {(p.porcentage <= 0) &&
                                    <i className="bi bi-exclamation-triangle-fill ms-2 text-warning"></i>
                                }
                            </div>

                            <div className="input-group input-group-sm">
                                <span className="input-group-text">%</span>
                                <input 
                                className="form-control"
                                type="number" 
                                min='0'
                                step='1'
                                id={`porcentage_${i}`}
                                name={`porcentage_${i}`}
                                onChange={handleInputChange}
                                value={p.porcentage}
                                />
                                <span className="position-absolute top-0 start-100 translate-middle badge rounded-pill bg-success" style={{zIndex: '2000'}} >
                                    { (item.costo + (item.costo * (p.porcentage/100))).toFixed(2) } Bs.
                                </span>
                            </div>
                        </div>
                    ))
                    }
                </div>
                <div className="window-footer">
                    <button type="submit" className="btn btn-success" disabled={actualizandoDatos} >
                        { actualizandoDatos&&
                            <div className="spinner-border spinner-border-sm me-2" role="status">
                                <span className="visually-hidden">Loading...</span>
                            </div>
                        }
                        { actualizacionExitosa &&
                            <i className="bi bi-check-circle-fill me-2"></i>
                        }
                        Guardar
                    </button>
                </div>
            </form>
        </div>
    </div>
  )
}
