import { tipoOracion } from "../../../../helpers/textConfig"

export const PreciosManual = ({formulario, formValues, handleInputChange, modoEdit, editConfiguracionPrecios}) => {
    
  return (
    <div>
        {
            formValues.map((p, index) => (
              <div key={index} className="row">
                <div className="col-5">{ tipoOracion(p.tipo) }: </div>
                <div className="col-6">
                  <div className="input-group mb-3">
                    <span className="input-group-text">Bs.</span>
                    <input 
                      type="number" 
                      min='0'
                      className="form-control py-1" 
                      placeholder={`${ p.precio }`}
                      name={`precio_${index}`}
                      id={`precio_${index}`}
                      onChange={handleInputChange}
                      step='0.0001'
                      value={ p.precio }
                      disabled={ modoEdit || editConfiguracionPrecios.auto}
                    />
                    <span className="position-absolute top-0 start-100 translate-middle badge rounded-pill bg-success" style={{zIndex: '2000'}} >
                      {formulario.values.costo !== ''?
                      parseFloat((((p.precio - formulario.values.costo) * 100) / formulario.values.costo).toFixed(1))
                      :
                      '-'
                      }%
                    </span>
                  </div>
                </div>
              </div>
            ))
        }
    </div>
  )
}
