import { useDispatch, useSelector } from "react-redux"
import { tipoOracion } from "../../../../helpers/textConfig";
import { useFormList } from "../../../../hooks/useFormList";
import { editarDocumentoFirebase } from "../../slices/productosThunk";


export const PreciosAutomatico = ({item, formValuesAuto, handleInputChangeAuto}) => {

  return (
    <div>
        {formValuesAuto.map((p,i)=>(
            <div key={i} className="row">
                <div className="col-5">{ tipoOracion(p.tipo) }: </div>
                <div className="col-6">
                    <div className="input-group mb-3">
                        {(p.porcentage <= 0) &&
                            <i className="bi bi-exclamation-triangle-fill text-warning position-absolute" style={{zIndex: '2000', left:'-30px', top:'5px'}}></i>
                        }
                        <span className="input-group-text">%</span>
                        <input 
                        className="form-control py-1"
                        type="number" 
                        min='0'
                        step='1'
                        id={`porcentage_${i}`}
                        name={`porcentage_${i}`}
                        onChange={handleInputChangeAuto}
                        value={p.porcentage}
                        />
                        <span className="position-absolute top-0 start-100 translate-middle badge rounded-pill bg-success" style={{zIndex: '2000'}} >
                            { (item.costo + (item.costo * (p.porcentage/100))).toFixed(2) } Bs.
                        </span>
                    </div>
                </div>
            </div>
        ))
        }
    </div>
  )
}
