import { useEffect, useState } from "react"
import { useDispatch, useSelector } from "react-redux"
import { tipoOracion, upperCamelCase } from "../../../../helpers/textConfig";
import { useFormik } from "formik";
import { useFormList } from "../../../../hooks/useFormList";
import { doc, updateDoc } from "firebase/firestore";
import { db } from "../../../../firebase/firebaseConfig";
import { finishUpdate, startUpdate } from "../../slices/productosSlice";
import { obtenerColeccionProductosParaProductosFirebase } from "../../slices/productosThunk";


export const ConfiguracionMultiplePrecios = ({setConfiguracionPreciosAutomaticos}) => {

    const [errorMessage, setErrorMessage] = useState({ msg:'', state: false });
    const [precioAutomatico, setPrecioAutomatico] = useState(true);
    const {precios, actualizandoDatos, actualizacionExitosa, items, marcas, categorias, cargandoAplicacion} = useSelector(s=>s.productos);
    const [checkPrecioAutomatico, setCheckPrecioAutomatico] = useState(true);
    const [formValues, handleInputChange,,,,,listAddArray ] = useFormList([]);
    const dispatch = useDispatch();

    const [listItems, setListItems] = useState(items.map(i => {
        const newItem = {
            id: i.id,
            marca: i.marca.toUpperCase(),
            categoria: i.categoria.toUpperCase(),
            modelo: i.modelo,
            nombre: i.nombre,
            select: false,
            imgUrl: i.imgUrl,
        }
        return newItem
    }));

    const datosBusqueda = useFormik({
        initialValues:{
            buscar:'',
            marca:'',
            categoria:''
        }
    });

    const showItems = listItems.filter(i => {
        if( i.marca.toLowerCase().includes(datosBusqueda.values.marca.trim().toLowerCase()) &&
            i.categoria.toLowerCase().includes(datosBusqueda.values.categoria.trim().toLowerCase()) ){
                if( i.nombre.toLowerCase().includes(datosBusqueda.values.buscar.trim().toLowerCase()) ||
                    i.marca.toLowerCase().includes(datosBusqueda.values.buscar.trim().toLowerCase()) ||
                    i.modelo.toLowerCase().includes(datosBusqueda.values.buscar.trim().toLowerCase())
                ) return i; 
            }
      });

    const handleCheckItem = (codigo) => {
        let newList = [...listItems];
        newList.forEach( i => {
            if( i.id === codigo ){
                i.select = !i.select;
                return ;
            }
        });
        setListItems(newList);
    }

    const selectAllItems = ({target}) =>{
        const { checked } = target;
        const idShowItems = showItems.map(i => i.id);
        let newList = [...listItems];
        
        newList.forEach( i => {
            if( idShowItems.includes(i.id)) i.select = checked;
            else i.select = false;
        });
        setListItems(newList);
    }

    const guardarConfiguracionPrecios = (e) => {
        e.preventDefault();
        const itemSelected = listItems.filter(i => i.select === true);
        
        if(itemSelected.length !== 0){
            dispatch( startUpdate() );
            if(precioAutomatico){
                const porcentage = {};
                formValues.forEach(v => {
                    porcentage[v.tipo] = v.precio? parseInt(v.precio):0;
                });
                itemSelected.forEach(async item => {
                    if(item.select){ // Vuelve a verificar que el item este seleccionado
                        const itemRef = doc(db, "/aplicaciones/productos/items/" + item.id);
                        await updateDoc(itemRef, {
                            configuracionPrecios: {
                                auto: checkPrecioAutomatico,
                                porcentage
                            }
                        })
                    }
                })
            }else{
                // console.log(formValues);
                listItems.forEach(async item => {
                    if(item.select){
                        const itemRef = doc(db, "/aplicaciones/productos/items/" + item.id);
                        await updateDoc(itemRef, {
                            preciosVenta: formValues,
                            "configuracionPrecios.auto": false
                        })
                    }
                })
            }
            
            dispatch( finishUpdate() );
            //Actualizamos toda la lista de Productos
            dispatch( obtenerColeccionProductosParaProductosFirebase() );
        }else{
            setErrorMessage({msg: 'No se selecciono ningun producto', state: true});
            setTimeout(() => {setErrorMessage({msg:'', state: false})}, 6000);
        }

    }

    useEffect(() => {
        let newTipoPrecios = precios.map(p=>({tipo: p.tipo, precio: 0}));
        listAddArray(newTipoPrecios);
    }, [])
    
  return (
    <div className="window">
        <div className="window-container">
            <div className="window-head">
                <span>CONFIGURAR PRECIOS DE MULTIPLES PRODUCTOS</span>
                <div className="btn-exit" onClick={ () => { setConfiguracionPreciosAutomaticos(s=>!s) } } >
                    <i className="bi bi-x"></i>
                </div>
            </div>

            <div className="window-body">
                <div className="container-fluid d-flex">
                    <div className="w-50" style={{height:'510px', overflow:'hidden', overflowY:'scroll'}} >
                        {showItems.map((i)=> (
                        <div key={i.id} className="list-group-item">
                            <div className='row' >
                                <div className="col-2 d-flex justify-content-center">
                                    <img src={i.imgUrl} style={{height:'80px'}} />
                                </div>
                                <div className="col d-flex justify-content-center align-items-center">{i.modelo}</div>
                                <div className="col d-flex justify-content-center align-items-center">{i.marca}</div>
                                <div className="col d-flex justify-content-center align-items-center">{i.categoria}</div>
                                <div className="col-1 d-flex justify-content-center align-items-center">
                                    {i.select ?
                                        <i 
                                        className="bi bi-check-circle-fill" style={{ color:'green', cursor:'pointer' }}
                                        onClick={()=>{handleCheckItem(i.id)}}
                                        ></i>
                                        :
                                        <i 
                                        className="bi bi-check-circle" 
                                        style={{ color:'#989898', cursor:'pointer' }}
                                        onClick={()=>{handleCheckItem(i.id)}} 
                                        ></i>
                                    }
                                </div>
                            </div>
                        </div>
                        ))}
                    </div>

                    <div className="w-50 p-4">
                        <div className="container">
                            <div className="row">
                                <div className="col-6">
                                    <div className='input-search' >
                                        <input 
                                            type="search" 
                                            placeholder='Buscar...'
                                            id='buscar'
                                            name='buscar'
                                            autoComplete='off'  
                                            onChange={datosBusqueda.handleChange}
                                            value={datosBusqueda.values.buscar}           
                                        />
                                        <i className="bi bi-search" style={{left:'15px'}}></i>
                                    </div>
                                </div>
                                
                                <div className="col-3 pe-1 p-0">
                                    <select 
                                    className="form-select form-select-sm"
                                    id='marca'
                                    name='marca'  
                                    onChange={datosBusqueda.handleChange}
                                    value={datosBusqueda.values.marca}                                        
                                    >
                                    <option value=''>Marcas</option>
                                    {
                                        marcas.map( m => (
                                        <option key={m.id} value={m.nombre}>{ upperCamelCase( m.nombre )}</option>
                                        ) )
                                    }

                                    </select>         
                                </div>
                                <div className="col-3 ps-1 p-0">
                                    <select 
                                    className="form-select form-select-sm"
                                    id='categoria'
                                    name='categoria' 
                                    onChange={datosBusqueda.handleChange}
                                    value={datosBusqueda.values.categoria}  
                                    >
                                    <option value=''>Categorias</option>
                                    {
                                        categorias.map( c => (
                                        <option key={c.id} value={c.nombre}>{ upperCamelCase( c.nombre )}</option>
                                        ) )
                                    }
                                    </select>
                                </div>
                            </div>

                            <div className="row mt-3">
                                <div className="form-check">
                                    <input className="form-check-input" type="checkbox" id="selectAll" onChange={selectAllItems}/>
                                    <label className="form-check-label" htmlFor="selectAll">
                                        Seleccionar todo
                                    </label>
                                </div>
                            </div>

                            <hr />

                            <div className="row mb-3">
                                <div className="d-flex justify-content-center btn-group">
                                    <div className={`btn ${precioAutomatico?'btn-primary':'btn-outline-primary'}`}
                                        onClick={() => {setPrecioAutomatico(true)}}
                                    >Precio automatico</div>
                                    <div className={`btn ${precioAutomatico?'btn-outline-primary':'btn-primary'}`}
                                        onClick={() => {setPrecioAutomatico(false)}}
                                    >Precio manual</div>
                                </div>                                
                            </div>



                            <form className="row" onSubmit={guardarConfiguracionPrecios}>
                                {formValues.map((p,i)=>(
                                    <div key={i} className="d-flex mb-2">
                                        <div className="col-5">
                                            <label htmlFor={`precio_${i}`}>
                                                {tipoOracion(p.tipo)}
                                            </label>
                                        </div>
                                        <div className="col-2">
                                            {(p.precio <= 0) &&
                                                <i className="bi bi-exclamation-triangle-fill ms-2 text-warning"></i>
                                            }
                                        </div>

                                        <div className="input-group input-group-sm">
                                            {precioAutomatico?
                                                <span className="input-group-text">%</span>
                                                :
                                                <span className="input-group-text">Bs.</span>
                                            }
                                            <input 
                                            className="form-control"
                                            type="number" 
                                            min='0'
                                            step='1'
                                            id={`precio_${i}`}
                                            name={`precio_${i}`}
                                            onChange={handleInputChange}
                                            value={p.precio}
                                            />
                                        </div>
                                    </div>
                                ))
                                }
                                {precioAutomatico&&
                                    <div className="form-check form-switch">
                                        <input className="form-check-input" 
                                        type="checkbox" 
                                        id="checkPrecioAutomatico"
                                        checked={checkPrecioAutomatico}
                                        onChange={({target}) => {setCheckPrecioAutomatico(target.checked)}}
                                        />
                                        <label className="form-check-label" htmlFor="checkPrecioAutomatico">Activar precio automatico</label>
                                    </div>
                                }
                                <button type="submit" className="btn btn-success mt-3" disabled={(actualizandoDatos || cargandoAplicacion)} >
                                { (actualizandoDatos || cargandoAplicacion) &&
                                    <div className="spinner-border spinner-border-sm text-white me-2" role="status">
                                        <span className="visually-hidden">Loading...</span>
                                    </div>
                                }
                                { actualizacionExitosa &&
                                    <i className="bi bi-check-circle-fill me-2"></i>
                                }
                                    Guardar
                                </button>

                                {errorMessage.state &&
                                    <div className="alert alert-danger mt-2 py-1" role="alert">
                                        {errorMessage.msg}
                                    </div>
                                }
                            </form>
                        </div>
                    </div>
                </div>
            </div>


        </div>
    </div>
  )
}
