import { useSelector } from "react-redux";
import { generarFechaAMD, generarFechaDMA } from "../../../../helpers/dateConfig";
import logo from '../../../../assets/svg/logo-letra.svg';
import { useEffect, useRef, useState } from "react";
import { pdfReporteCompras } from "../../pdf/pdfReporteCompras";
import { useForm } from "../../../../hooks/useForm";


export const ReporteCompras = ({ setReporteCompras, valuesObj }) => {
    const [mostrarDetalles, setMostrarDetalles] = useState(false);
    const { compras } = useSelector(s => s.compras);
    const { marcas } = useSelector(s => s.productos);
    const [ listItems, setListItems ] = useState([]);
    const [ busqueda, handleInputChange] = useForm({nombre:'', marca:''});
    const table = useRef();

    let totalShowListItems = 0;
    const showListItems = listItems.filter(i => {
        if(i.marca.toLocaleLowerCase().includes(busqueda.marca.toLocaleLowerCase())){
            if(i.nombre.toLocaleLowerCase().includes(busqueda.nombre.toLocaleLowerCase())){
                totalShowListItems += i.total;
                return i;
            }
        }
    });

    const showCompras = compras.filter( c =>{
        if( c.proveedor.toLocaleLowerCase().includes(valuesObj.proveedor.toLocaleLowerCase()) ){
          return c;
        }});
    showCompras.reverse();

    const calcularSaldo = (c) => {
        let saldo = 0;
        c.saldoPagos.forEach(p => {
            saldo += p.monto           
        });
        return c.total - saldo;
    }
    const calcularTotales = () => {
        let sumPagado = 0;
        let sumRestante = 0;
        let sumIva = 0;
        let sumSubtotal = 0;
        let sumTotal = 0;

        showCompras.forEach( c => {
            const saldo = calcularSaldo(c);
            sumPagado += c.total - saldo;
            sumRestante += saldo;
            sumIva += (c.factura? c.factura.iva : 0);
            sumSubtotal += (c.factura? c.factura.subtotal : c.total);
            sumTotal += c.total;
        });
        return{ sumPagado, sumRestante, sumIva, sumSubtotal, sumTotal }
    }
    const totales = calcularTotales();

    const descargarReporteCompras = () => {
        const id = table.current.id;
        const datos = {
            fechaInicial: generarFechaDMA(valuesObj.fechaInicio),
            fechaFinal: generarFechaDMA(valuesObj.fechaFinal)
        }
        pdfReporteCompras(id, datos);
    }

    useEffect(() => {
        let newListCompras = [];
        for (let i = 0; i < compras.length; i++) {
            const c = compras[i];
            if( c.proveedor.toLocaleLowerCase().includes(valuesObj.proveedor.toLocaleLowerCase()) ){
                c.items.forEach(it => {
                    const item = {
                        numero: c.numero,
                        fecha: c.fecha,
                        proveedor: c.proveedor,
                        nombre: it.nombre,
                        codigo: it.modelo,
                        marca: it.marca,
                        cantidad: it.cantidad,
                        cantidadResivida: it.cantidadResivida,
                        precio: it.precio,
                        total:  (it.cantidad * it.precio)
                    }
                    newListCompras.push(item);
                })
            }
        }
        newListCompras.reverse();
        setListItems(newListCompras);
    }, [])
    

  return (
    <div className="window">
        <div className="window-container">
            <div className="window-head">
                <span>REPORTE DE COMPRAS</span>
                <div className="btn-exit" onClick={ () => { setReporteCompras(s => !s) } } >
                    <i className="bi bi-x"></i>
                </div>
            </div>
            <div className="window-body">

                <div className="container-fluid">
                    <div className="row">
                        <div className="col">
                            <img src={logo} style={{ height:'80px' }}/> 
                        </div>
                        <div className="col">
                            <p> <span className="fw-bold"> Desde: </span> { generarFechaDMA(valuesObj.fechaInicio) }</p>
                            <p> <span className="fw-bold"> Hasta: </span> { generarFechaDMA(valuesObj.fechaFinal) }</p>
                        </div>
                        </div>
                </div>


                <table className="table" id="tableReporteCompras" ref={table} >
                    <thead>
                        {mostrarDetalles?
                        <tr>
                            <th>N/C</th>
                            <th>Fecha</th>
                            <th>Proveedor</th>
                            <th>Producto</th>
                            <th>Cod.</th>
                            <th>Marca</th>
                            <th>Cant.</th>
                            <th>Recivido</th>
                            <th>P/Unit</th>
                            <th>Total</th>
                        </tr>
                        :
                        <tr>
                            <th>Fecha</th>
                            <th>Proveedor</th>
                            <th>Compra</th>
                            <th>Items</th>
                            <th>Pagado</th>
                            <th>Restante</th>
                            <th>IVA</th>
                            <th>Subtotal</th>
                            <th>Total</th>
                        </tr>
                        }
                    </thead>
                    {mostrarDetalles?
                        <tbody>
                            {showListItems.map((i,index) => (
                                <tr key={index} >
                                    <td> { i.numero } </td>
                                    <td> { generarFechaDMA(generarFechaAMD(i.fecha)) } </td>
                                    <td> { i.proveedor } </td>
                                    <td> { i.nombre } </td>
                                    <td> { i.codigo }</td>
                                    <td> { i.marca }</td>
                                    <td> { i.cantidad } </td>
                                    <td> { i.cantidadResivida || 0} </td>
                                    <td> { i.precio } Bs. </td>
                                    <td> { i.total } Bs. </td>
                                </tr>
                            ))}
                        </tbody>
                        :
                        <tbody>
                            {showCompras.map(c => (
                                <tr key={c.id} >
                                    <td> { generarFechaDMA(generarFechaAMD(c.fecha)) } </td>
                                    <td> { c.proveedor } </td>
                                    <td className="text-uppercase" > Compra Nº{ c.numero } </td>
                                    <td> { c.items.length } </td>
                                    <td> { c.total - calcularSaldo(c) } Bs. </td>
                                    <td> { calcularSaldo(c) } Bs. </td>
                                    <td> { c.factura ? c.factura.iva : 0 } </td>
                                    <td> { c.factura ? c.factura.subtotal : c.total } </td>
                                    <td> { c.total } Bs. </td>
                                </tr>
                            ))}
                        </tbody>
                    }
                    <tfoot>
                        {mostrarDetalles?
                            <tr>
                                <th colSpan='9' >Total</th>
                                <th>{ totalShowListItems } Bs.</th>
                            </tr>
                            :
                            <tr>
                                <th colSpan='4' >Total</th>
                                <th>{ totales.sumPagado } Bs.</th>
                                <th>{ totales.sumRestante } Bs.</th>
                                <th>{ totales.sumIva } Bs.</th>
                                <th>{ totales.sumSubtotal } Bs.</th>
                                <th>{ totales.sumTotal } Bs.</th>
                            </tr>
                        }
                    </tfoot>
                </table>
            </div>

            <div className="window-footer">
                {mostrarDetalles?
                    <>
                        <div className="btn btn-secondary" onClick={() => {setMostrarDetalles(s=>!s)}} >Ver por compra</div>
                        <div className="ms-2" >
                            <select 
                            className='form-select form-select-sm text-capitalize' 
                            name='marca'
                            onChange={handleInputChange}
                            value={busqueda.marca}  
                            >
                                <option className="text-capitalize" value=''>Marcas</option>
                                {marcas.map(m => (
                                    <option className="text-capitalize" key={m.id} value={m.nombre}>{m.nombre}</option>
                                ))}
                            </select>
                        </div>
                        <div className='input-search ms-2 me-auto' >
                            <input 
                            type="search" 
                            placeholder='Buscar...'
                            name='nombre'
                            autoComplete='off'
                            onChange={handleInputChange}
                            value={busqueda.nombre}           
                            />
                            <i className="bi bi-search" style={{left:'15px'}} ></i>
                        </div>
                    </>
                    :
                    <div className="btn btn-secondary me-auto" onClick={() => {setMostrarDetalles(s=>!s)}} >Ver por items</div>
                }
                <div className="btn btn-danger" onClick={descargarReporteCompras} ><i className="bi bi-file-earmark-pdf-fill"></i>Descargar</div>
            </div>
        </div>
    </div>
  )
}
