import { createSlice } from '@reduxjs/toolkit';

export const sidebarSlice = createSlice({
   name: 'sidebar',
   initialState: {
        detallesTurno: { 
            turno:'TURNO', 
            inicio:'', 
            fin:'..:..:..', 
            ventas: [],
            pagos: [],
            precioBase: '',
            tipoPago: '',
            vendedor: '', //new Vendedor(cargo, contacto, nombre, uid),
            cliente: '', //new Cliente('', '','','','','',`T. ${v.turno} | ${horaInicio} - .. : .. : ..`),
            active: false,
            fecha: ''
        },
        onLoad: false,
        numeroVenta: 0
   },
   reducers: {
      iniciarTurno: (state, {payload} ) => { // turno, inicio, vendedor, fecha
         if(payload.ventas?.length>0){ //Modifica el numero de venta revisando el ultimo producto vendido
            const ultimaVenta = payload.ventas[payload.ventas.length-1];
            state.numeroVenta = ultimaVenta.numeroVenta;           
         }
         state.detallesTurno = {...payload};
      },
      finalizarTurno: (state) => {
         const newDetallesTurno = { 
            turno:'TURNO', 
            inicio:'', 
            fin:'..:..:..', 
            ventas: [],
            pagos: [],
            precioBase: '',
            tipoPago: '',
            vendedor: '',
            cliente: '',
            active: false,
            fecha: ''
         };
         state.detallesTurno = {...newDetallesTurno};
         state.numeroVenta = 0; 
      },
      startLoading: (state) => {
         state.onLoad = true;
      },
      finishLoading: (state) => {
         state.onLoad = false;
      },
      agregarVentas: (state, {payload}) => {
         state.numeroVenta = state.numeroVenta + 1; 
         state.detallesTurno.ventas = [ ...state.detallesTurno.ventas, ...payload ];
      },
      editarVentas: (state, {payload}) => {
         state.numeroVenta = state.numeroVenta + 1; 
         state.detallesTurno.ventas = [ ...payload ];
      }

   }
});


export const { agregarVentas,editarVentas, iniciarTurno, finalizarTurno, startLoading, finishLoading } = sidebarSlice.actions;