import { useFormik } from "formik";
import { useEffect, useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import { iniciarTurnoDB, verificarInicioTurnoDB } from "../slice/sidebarThunk";
import { TurnoDetalles } from "../windows/TurnoDetalles";
import { DetallesVenta } from "../../../pages/ventas/windows/DetallesVenta";

export const Turno = ({stateSitebar}) => {
  const formatoVenta = {
    cliente: {codigo: '', contacto: '',correo: '',direccion: '',id: '',nit: '',nombre: ''},
    factura: { iva: 0, it: 0, subtotal: 0, total: 0 },
    fecha: new Date(),
    idCliente: '',
    items:[],
    numero:0,
    pagos: [
      {detalle:'', 
      fecha:new Date(), 
      monto:0, 
      usuario:{nombre:'', uid:''}
    }],
    precioBase: '',
    tipoPago: '',
    total: 0,
    vendedor: {cargo:'', contacto:'', nombre:'', uid:''}
  }

  const dispatch = useDispatch();
  const [turnoDetalles, setTurnoDetalles] = useState(false) // Ventana para ver los detalles del tueno
  const [detallesVenta, setDetallesVenta] = useState(false);
  const [venta, setVenta] = useState(formatoVenta);

  const {cargo, nombre, contacto, uid} = useSelector(s => s.login);
  const { detallesTurno, onLoad } = useSelector(s => s.sidebar);

  const formInicio = useFormik({
    initialValues:{
      turno: new Date().getHours() < 12 ? 'MAÑANA':'TARDE'
    },
    onSubmit: (v) => {
      const fechaActual = new Date();
      const hora = fechaActual.getHours();
      const minutos = fechaActual.getMinutes();
      const segundos = fechaActual.getSeconds();
      const horaInicio = hora + ":" + minutos + ":" + segundos; 

      const newDetallesTurno = {
        turno: v.turno,
        inicio: horaInicio,
        vendedor: {cargo, contacto, nombre, uid},
        fecha: Date.now()
      }
      dispatch(iniciarTurnoDB({...newDetallesTurno}));
    }
  });

  useEffect(() => {
    dispatch( verificarInicioTurnoDB( uid ) );
  }, [])
  

  return (
    <div className={`main-turno ${detallesTurno.active&&'start'}`} >
      {/* VENTANAS */}
      {turnoDetalles&&
      <TurnoDetalles
        setTurnoDetalles={setTurnoDetalles}
        setDetallesVenta={ setDetallesVenta }
        setVenta={ setVenta }
      />
      }
      {detallesVenta&&
        <DetallesVenta
        setDetallesVenta={ setDetallesVenta }
        venta={ venta }
        />
      }


        <span className="main-turno-badge">{ detallesTurno.turno }</span>
        {detallesTurno.active?
          <div className="d-flex detalles-turno" >
            <table className="table-turno" >
              <tbody>
                <tr>
                  <th>Inicio</th>
                  <td>{ detallesTurno.inicio}</td>
                </tr>
                <tr>
                  <th>Ventas</th>
                  <td> <span className="bg-secondary rounded-pill px-2">{ detallesTurno.ventas?.length}</span></td>
                </tr>
              </tbody>
            </table>

            <div className="d-flex flex-column justify-content-center align-items-center">
              {stateSitebar?
              <button 
              // type="submit" 
              onClick={() => { setTurnoDetalles(!turnoDetalles) }}
              className="btn btn-sm btn-primary ms-3 mb-1" 
              disabled={onLoad} > Detalles 
              </button>  
              :
              <button 
              // type="submit" 
              onClick={() => { setTurnoDetalles(!turnoDetalles) }}
              className="btn btn-sm btn-primary py-1 px-2" 
              disabled={onLoad} > <i className="bi bi-box-arrow-up-right"></i> 
              </button>
              }
            </div>

          </div>
          :
          <form className="d-flex select-turno" onSubmit={formInicio.handleSubmit} >
              <select 
              name="turno"
              id="turno" 
              className="form-select form-select-sm"
              value={formInicio.values.turno}
              onChange={formInicio.handleChange}
              >
                  <option value="MAÑANA">Mañana</option>
                  <option value="TARDE">Tarde</option>
              </select>
              
              { stateSitebar?
              <button type="submit" className="btn btn-sm btn-primary ms-3" disabled={onLoad} > Iniciar </button>
              :
              <button type="submit" className="btn btn-sm btn-primary py-0 px-1" disabled={onLoad}> <i className="bi bi-play-fill"></i> </button>
              }
          </form>
          
        }
    </div>
  )
}
