
export const TurnoAlertNotification = ({ setTurnoAlertNotification, titulo, mensaje, funcion }) => {
  return (
    <div className='container-alert' >
      <div className="alert-title"> {titulo} </div>

      <div className="alert-body text-black">
      {mensaje}
      </div>

      <div className="alert-footer">
        <button 
        className='alert-footer-btn-primary'
        onClick={()=>{
          funcion();
          setTimeout(()=>{
            setTurnoAlertNotification(s=>!s)
          }, 1000);
        }}
        >Aceptar</button>

        <button 
        className='alert-footer-btn-secondary'
        onClick={()=>{ setTurnoAlertNotification(s=>!s) }}  
        >Cancelar</button>
      </div>     

    </div>
  )
}
