
export const Footer = (
  { registrarProducto , setRegistrarProducto, windowConfig, setWindowConfig, reporte, setReporte }
  ) => {
  
  return (
    <div className='aplication-footer' >
      <div className="container-fluid">
        <div className="row">
          <div className="col-10">
            <div className='btn btn-primary me-3 d-none d-md-inline-block ' onClick={()=>{ setRegistrarProducto(!registrarProducto) }} >Nuevo Producto</div>
            <div className='btn btn-secondary d-none d-md-inline-block ' onClick={()=>{ setReporte(!reporte) }}  >Generar Reporte</div>
            <div className='btn btn-primary me-3 d-md-none ' onClick={()=>{ setRegistrarProducto(!registrarProducto) }} > <i className="bi bi-plus-circle"></i> </div>
            <div className='btn btn-secondary d-md-none' onClick={()=>{ setReporte(!reporte) }}  ><i className="bi bi-card-text"></i></div>
          </div>
          <div className="col-2">
            <div className="btn-icon-secondary ms-auto" onClick={()=>{ setWindowConfig(!windowConfig) }} ><i className="bi bi-gear-fill"></i></div>
          </div>
        </div>
      </div>
    </div>
  )
}
